/* RAM only, IRQs off, second core not running: no flash fetch from here to the end */
static RAMFN void fm1_clk320_switch(const fm1_clk320_t *p)
{
    uint32_t pll2 = p->pll2_con1, sdiv = p->sys_div, baud = p->sfc_baud, scon = p->sfc_con, b9 = p->cache_b9;
    uint32_t usb = FCLK_USB_CON0, sdr = FCLK_SDR_CON1, con2 = FCLK_CLK_CON2, r = FCLK_CLK_CON0;
    if (r & 0x100u) {                                     /* SYS onto RC16M */
        r = (r | 2u) & ~0x100u;
        FCLK_SYNC(); FCLK_WAIT_CACHE(); FCLK_SYNC(); FCLK_WAIT_SFC();
        FCLK_CLK_CON0 = r;
        FCLK_SYNC(); fclk_spin(300);
    }
    FCLK_SYNC(); FCLK_WAIT_CACHE(); CACHE_CON &= ~0x300u;     /* cache off */
    FCLK_SYNC(); FCLK_WAIT_SFC(); SFC_CON &= ~1u;            /* flash controller off */
    FCLK_SYNC(); fclk_spin(60u * 4u);                         /* 60 us at RC16M, x2 margin */
    FCLK_USB_CON0 = usb;                                      /* the SDK's write order */
    FCLK_SDR_CON1 = sdr;
    FCLK_PLL2_CON1 = pll2;
    FCLK_CLK_CON2 = con2;
    FCLK_SYS_DIV = sdiv;
    FCLK_SYNC(); fclk_spin(1000u * 4u);                       /* 1 ms: the PLL settles */
    FCLK_SYNC(); FCLK_WAIT_CACHE(); FCLK_SYNC(); FCLK_WAIT_SFC();
    FCLK_SFC_BAUD = baud;                                     /* flash controller back, retimed */
    SFC_CON = scon;
    FCLK_SYNC(); fclk_spin(60u * 4u);
    CACHE_CON |= 0x100u | b9;                                 /* cache back */
    FCLK_SYNC();
    r = FCLK_CLK_CON0;
    if (!(r & 0x100u)) {                                  /* SYS back onto the PLL */
        r |= 0x100u;
        FCLK_SYNC(); FCLK_WAIT_CACHE(); FCLK_SYNC(); FCLK_WAIT_SFC();
        FCLK_CLK_CON0 = r;
        FCLK_SYNC(); fclk_spin(300);
    }
}

static void lcd_data(const void *p, uint32_t n)
{
    if (!n)
        return;                    /* SPI_CNT = 0 never completes */
    lcd_sync();
    fm1_lcd_send_data(p, n);
    lcd_busy = 1;                  /* completed by lcd_sync */
}

static void lcd_window(uint32_t x0, uint32_t y0, uint32_t x1, uint32_t y1)
{
    lcd_sync();
    lcd_small[0] = (uint8_t)(x0 >> 8);
    lcd_small[1] = (uint8_t)x0;
    lcd_small[2] = (uint8_t)(x1 >> 8);
    lcd_small[3] = (uint8_t)x1;
    lcd_cmd(0x2A);
    lcd_data(lcd_small, 4);
    lcd_small[4] = (uint8_t)(y0 >> 8);       /* own bytes: the x transfer may still read [0..3] */
    lcd_small[5] = (uint8_t)y0;
    lcd_small[6] = (uint8_t)(y1 >> 8);
    lcd_small[7] = (uint8_t)y1;
    lcd_cmd(0x2B);
    lcd_data(lcd_small + 4, 4);
    lcd_cmd(0x2C);
}

static void fm1__p33_op(uint32_t op, uint32_t a, uint8_t d)   /* 0 wr, 1 or, 2 and, 3 xor */
{
    fm1__p33_cs(a);
    fm1__p33_xfer((uint8_t)((op << 5) | ((a >> 8) & 3u)));
    fm1__p33_xfer((uint8_t)a);
    fm1__p33_xfer(d);
    FM1_P33_CON &= ~((1u << 0) | (1u << 8));
}

/* note into track k's chord: a new chord (fresh), or one more note of the one it plays */
static void fol_add(uint32_t k, uint32_t note, int fresh)
{
    fol_src_t *s = &fol_src[k];
    if (fresh || !s->pc) {
        s->pc = 0;
        s->lo = 127;
        s->hi = 0;
    }
    s->pc |= (uint16_t)(1u << (note % 12u));
    s->lo = (uint8_t)(note < s->lo ? note : s->lo);
    s->hi = (uint8_t)(note > s->hi ? note : s->hi);
    s->last = (uint8_t)note;
    s->root = (uint8_t)fol_root(s->pc, s->lo);
}

static uint32_t midi_targets(uint32_t ch)
{
    return midi_channel(ch)->targets | (1u << trk_index(midi_track(ch)));
}

/* (phase 5) the step track t enters may end where its staged pattern comes in (LOOP: its pass's last, the passes
 * made; BAR, BEAT, NOW: whenever one is staged, the point not known here): the step after it is not played early
 * (seq.c seq_enter: NUDGE), it would be the outgoing pattern's */
static int launch_ahead(const track_t *t, uint32_t len)
{
    uint32_t k = trk_index(t);
    const launch_t *q = &launch_q[k];
    if (!q->armed)
        return 0;
    return q->mode != LAUNCH_LOOP || (seq_pass_last(t, len) && (uint16_t)(take_pass[k] - take_p0[k]) >= q->reps);
}

/* a level lv (0..127, square law: 127 as it is, 64 a quarter) on the block's amplitude ramp, not per sample: m itself
 * at 127 (and out of range), else its copy in *ml. DRUM's lane LEVELs (#97), (Skiff, #21) a user sample's sounds' */
static const vmod_t *vmod_level(const vmod_t *m, vmod_t *ml, int32_t lv)
{
    int32_t gl = lv * lv * 2 + (lv * lv >> 6);           /* Q15, 64: 8256 */
    if ((uint32_t)lv >= 127u)
        return m;
    *ml = *m;
    ml->amp0 = (m->amp0 >> 4) * gl >> 11;
    ml->amp1 = (m->amp1 >> 4) * gl >> 11;
    return ml;
}

/* the step clock over n samples and the SLICER on b (0: the clock only, the track is silent) */
static void slicer_track(const track_t *t, int32_t *b, uint32_t n)
{
    uint32_t k = (uint32_t)(t - trk), i = 0;
    sl_t *s = &sl[k];
    int act = b && (t->p[P_SLCR] != SL_OFF || s->gc || s->w);
    while (i < n) {
        uint32_t m;
        if (s->pos >= s->len)
            sl_enter(t, s);
        m = s->len - s->pos;
        if (m > n - i)
            m = n - i;
        if (act)
            sl_seg(t, s, sl_buf[k], b + i, 0, 0, m);
        s->pos += m;
        i += m;
    }
}

/* the copy to edit for user slot k: the MAN slices in use, or the AUTO ones when there are none (those that keep
 * SLC_MIN apart and from the end); 0 = no material in the slot */
static slc_man_t *slc_man_begin(uint32_t k)
{
    const slc_src_t *s = k < SMP_USER_SLOTS ? slc_get(k + 1u) : 0;
    const slc_man_t *cur;
    slc_man_t *m;
    uint32_t i;
    if (!s)
        return 0;
    cur = &slc_man[k][slc_man_cur[k] & 1u];
    m = &slc_man[k][(slc_man_cur[k] & 1u) ^ 1u];
    if (cur->n) {
        *m = *cur;
        return m;
    }
    m->n = 0;
    m->end = 0;
    for (i = 0; i < s->nauto; i++)
        if (s->apos[i] < s->len && s->len - s->apos[i] >= SLC_MIN &&
            (!m->n || s->apos[i] - m->pos[m->n - 1u] >= SLC_MIN)) {
            m->pos[m->n] = s->apos[i];
            m->st[m->n++] = s->ast[i];
        }
    return m;
}

static uint32_t st_sector(uint32_t obj, uint32_t copy)  /* flash offset of copy A (0) / B (1) */
{
    return ST_SMK_BASE + (ST_SMK_ORDER[obj % OBJ_COUNT] * 2u + (copy & 1u)) * ST_SECTOR;
}

/* slot from flash into RAM (format 7, or format 6 / 5 / 4 / 3 / 2 / 1 converted; (2.0) SKF3, SKF4, and of a format of
 * before its magic alone: OLD FORMAT, proj_old) */
static void proj_fetch(uint32_t slot)
{
    project_store_t *q = &proj_slot[slot & 3u];
    const proj_fmt_t *f;
    int n;
    proj_wire_gen++;
    n = st_load(OBJ_PROJECT0 + (slot & 3u), proj_wire_u.raw, sizeof proj_wire_u.raw);   /* ((2.0) a longer one too) */
    f = proj_fmt_of(proj_wire_u.raw, n);           /* (phase 5, 6, 2.0) SKF2 .. SKF4 stay as they are: they name their
                                                   * patterns */
    if (!proj_import(&proj_scratch, proj_wire_u.raw, n))
        q->align = n >= 8 && proj_old_magic(proj_wire.align) ? proj_wire.align : 0u;
    else {
        proj_bound(&proj_scratch);
#if FELUCCA_LEGACY
        if (!(f ? proj_pack2(q, &proj_scratch, f) : proj_pack(q, &proj_scratch)))
#else
        if (!proj_pack2(q, &proj_scratch, f))
#endif
            memset(q->raw, 0, 4);
    }
}

