/* set a row (v below menu_n(row)) and do what the menu does on a change: the palette, the EQ and USB LEVEL at once;
 * LARGE, ANIM, LEDS, HOLD, the flags are read where they are used, every frame;
 * USB SERIAL when the menu has closed (usb_serial_apply). Saved by the caller (menu_close, the editor) */
static void menu_put(uint32_t row, uint32_t v)
{
    const menu_flag_t *f = menu_flag(row);
    if (f) {
        if (f->bit & PREF_REC)
            ui_rec_prefs = (uint8_t)(v ? ui_rec_prefs | f->bit >> 8 : ui_rec_prefs & ~(f->bit >> 8));
        else
            ui_prefs = (uint8_t)(v ? ui_prefs | f->bit : ui_prefs & ~f->bit);
        fx_usb_fixed = (ui_prefs & PREF_USB_FIXED) != 0u;   /* (at once; every frame too: ui_input) */
        return;
    }
    switch (row) {
    case MI_COLOR:                                     /* ((Skiff #27) CUSTOM: the stored colours in their look) */
        CPAL_BYTE = (uint8_t)(v >= NPALETTES ? CPAL_BYTE | 2u : CPAL_BYTE & ~2u);
        settings.palette = v >= NPALETTES ? CPAL_BYTE >> 2 & 7u : v;   /* (a look past QUARK: palette_set wraps it) */
        theme_apply();                                 /* (the menu signature redraws) */
        ui.force = 1;
        break;
    case MI_PHEAD: ui_ph_line = (uint8_t)(v & 1u); ui.force = 1; break;
    case MI_LOWCUT: settings.lowcut = v; fx_lowcut = (uint8_t)v; break;
    case MI_HOLD: settings_hold = (uint8_t)v; break;
    case MI_SCROFF: scr_put(v); break;                 /* (read every frame: ui.c scr_frame) */
    case MI_LEDS: settings_leds = LEDS_MENU[v]; break;
    case MI_CLICK: case MI_CLKLVL: case MI_COUNTIN: rp_put(row - MI_CLICK, v); break;   /* (at once: click.c, seq.c) */
    case MI_CLOCK: song.g[G_CLOCK] = (int16_t)v; break;   /* ((Skiff U3) the unit's: ui.c unit_g_poll keeps them) */
    case MI_ROUTE: song.g[G_ROUTE] = (int16_t)v; break;
    case MI_TCH1: case MI_TCH2: case MI_TCH3: case MI_TCH4: case MI_TCH5: case MI_TCH6:   /* ((1.3) the ISR reads it */
        ui_mch(row - MI_TCH1) = (uint8_t)((v - (row - MI_TCH1)) & 15u);                 /* at its next block) */
        break;
    case MI_TUNE: song.g[G_TUNE] = (int16_t)((int32_t)v - 50); break;
#if BOARD_SMK37
    case MI_KVEL: SMK_KV_BYTE = (uint8_t)(v % SMK_KV_N); smk_kv_mode = SMK_KV_BYTE; break;
#endif
    case MI_HINTS: ui_hints_off = (uint8_t)(v & 1u); ui.force = 1; break;
    case MI_PREVIEW:                                   /* ((Skiff 1.3) a bit of CPU2_BYTE) */
        CPU2_BYTE = (uint8_t)(v & 1u ? CPU2_BYTE | 2u : CPU2_BYTE & ~2u);
        break;
    case MI_RETURN: RET_BYTE = (uint8_t)(RET_BAR - v % 3u); break;   /* ((2.0) ui.c ret_mode) */
#if FELUCCA_CPU2
    case MI_CPU:                                       /* ((Skiff 1.3) the second core: started at power-on only, main.c) */
        CPU2_BYTE = (uint8_t)(v ? CPU2_BYTE | 1u : CPU2_BYTE & ~1u);
        settings_save();                               /* (at once, not at the menu's close: a restart follows; playing,
                                                        * at STOP, and the row says STOP till then) */
        break;
#endif
    case MI_CLK:                                       /* ((Skiff) the clock: switched at boot only, main.c; saved as CPU) */
        CPU2_BYTE = (uint8_t)(v ? CPU2_BYTE | 4u : CPU2_BYTE & ~4u);
        settings_save();
        break;
    }
}

static int ent_on(uint32_t k, uint32_t e) { return bank_used(k, e) || ent_rest(k, e); }   /* (#28) a pattern or a REST */
/* (2.0, #44, the user's pick 3A and the join sheet's A) a chain: track k's entries on CHAIN (REPS_CHAIN) into the
 * next, each a pattern or a REST: one pattern wherever the track plays them (song_poll, bank_switch), edited as one
 * (chain_cursor). Entry e chains into e + 1 */
static int ent_link(uint32_t k, uint32_t e)
{
    return e + 1u < NENT && lists.ent[k][e][1] == REPS_CHAIN && ent_on(k, e) && ent_on(k, e + 1u);
}

/* how many entries name pattern id: the lists now (but track k's entry e), the saved projects' */
static uint32_t pat_refs(uint32_t id, uint32_t k, uint32_t e)
{
    uint32_t n = proj_slot_refs(id), t, j;
    for (t = 0; t < NTRK; t++)
        for (j = 0; j < NENT; j++)
            n += (t != k || j != e) && lists.ent[t][j][0] == id + 1u;
    return n;
}

/* OCT+: KNOB 2's pick into the entry (a pattern; the track on the entry: it comes in, at once stopped, at LAUNCH
 * playing), COPY: a new pattern, a copy of the entry's (the track's edits in it first), the entry's then (the track on
 * it: on the copy); no pick: the entry played (entry_ui). What happened, said. (2.0, #32, the user's pick 1A) NEW: a
 * new empty pattern (the first free number, the track's LEN .. DIR), then as a pattern put in; (#33) COPY+: the copy
 * into the first empty entry after the entry (its REPS too), the entry as it was; ((#44) on a chain: every part's,
 * into as many empty entries in a row after it, a chain again) */
/* (Skiff W3) .. into track k's entry e (the editor's LIST SET, COPY too): 0 done, else entry_go's rc (the track on the
 * entry), 1 NOTHING TO COPY (COPY+: NO EMPTY ENTRY AFTER), 4 PATTERNS FULL */
static int song_put(uint32_t k, uint32_t e, uint32_t p)
{
    uint32_t id = ent_pat(k, e), n = NPAT, f = p == SPICK_COPYP ? ent_free_after(k, e) : e, b0, b1, j;
    uint8_t nid[NENT];
    char b[24], c[4];
    if (p == SPICK_NEW) {
        bank_poll();
        rec_empty(bk_rec, &trk[k]);
        if ((n = pool_alloc()) == NPAT || pat_keep_now(n, bk_rec)) {
            ui_way("PATTERNS FULL", WAY_PATTERNS);
            return 4;
        }
    }
    if (p != SPICK_COPY && p != SPICK_COPYP) {
        if (p == SPICK_NEW)
            p = n + 1u;
        lists.ent[k][e][0] = (uint8_t)p;           /* (p: the id + 1, as the entry keeps it; (#28) PAT_REST) */
        bk.gen++;
        if (lists.cur[k] == e)
            return entry_go(k, e);
        song_tag(b, k, e);
        pat_num(c, p - 1u);
        str_cpy(b + 4, n < NPAT ? " NEW " : " SET ", sizeof b - 4u);
        str_cpy(b + 9, p == PAT_REST ? "REST" : c, sizeof b - 9u);
        ui_message(b);
        return 0;
    }
    if (f == NENT) {
        ui_message("NO EMPTY ENTRY AFTER");
        return 1;
    }
    if (id == PAT_NONE) {
        ui_way("NOTHING TO COPY", "");
        return 1;
    }
    bank_poll();
    if (p == SPICK_COPYP) {                        /* ((2.0, #44) COPY+ on a chain: all of it, a chain again */
        ent_block(k, e, &b0, &b1);
        (void)copy_ids(k, e, nid);
    } else {
        b0 = b1 = e;
        nid[0] = (uint8_t)(pool_alloc_after(id) + 1u);
    }
    for (j = b0; j <= b1; j++) {                   /* (each part's copy, a REST as it is; the entries named after) */
        uint32_t o = ent_pat(k, j);
        if (!nid[j - b0]) {
            nid[j - b0] = (uint8_t)PAT_REST;
            continue;
        }
        n = nid[j - b0] - 1u;
        if ((trk_pid[k] == o + 1u && trk_keep(k)) || n == NPAT || pat_read(o, bk_rec) || pat_keep_now(n, bk_rec)) {
            ui_way("PATTERNS FULL", WAY_PATTERNS);
            return 4;
        }
    }
    for (j = b0; j <= b1; j++) {
        lists.ent[k][f + j - b0][0] = nid[j - b0];
        lists.ent[k][f + j - b0][1] = lists.ent[k][j][1];
        memcpy(lists.snd[k][f + j - b0], lists.snd[k][j], 2);   /* ((2.0, #30) its sound too) */
    }
    if (trk_pid[k] == id + 1u && lists.cur[k] == f)
        trk_pid[k] = nid[0];                       /* (the copy the track's from here: the same steps, the same sig) */
    bk.gen++;
    str_cpy(b, "COPIED ", sizeof b);
    if (b1 > b0) {                                 /* "COPIED A-B TO F-G" */
        b[7] = (char)('A' + b0), b[8] = '-', b[9] = (char)('A' + b1);
        str_cpy(b + 10, " TO ", sizeof b - 10u);
        b[14] = (char)('A' + f), b[15] = '-', b[16] = (char)('A' + f + b1 - b0), b[17] = 0;
    } else {
        pat_num(b + 7, id);
        str_cpy(b + 9, " TO ", sizeof b - 9u);
        pat_num(b + 13, n);
        if (f != e) {                              /* "COPIED 06 TO 22 AT F" */
            str_cpy(b + 15, " AT ", sizeof b - 15u);
            b[19] = (char)('A' + f);
            b[20] = 0;
        }
    }
    ui_message(b);
    return 0;
}

/* One SysEx message into usb.c's ring, or -2 (busy) when it has no room for all of it: never waits */
static int mirror_send(const uint8_t *m, unsigned n)
{
    if (!usb.config)
        return -1;
    if (SXQ - (so_w - so_r) < (n + 2u) / 3u + 1u)
        return -2;
    return ota_wire_send(m, n) ? -1 : 0;
}

